style.css:
@-moz-document domain("roblox.com") {
/* ===== BASE BACKGROUND ===== */

body {
    background:
        linear-gradient(rgba(0,0,0,0.80), rgba(0,0,0,0.80)),
        url("https://files.catbox.moe/f435i9.jpg")
        center center fixed !important;

    background-size: cover !important;
}

/* ===== DARK OVERLAY ===== */

body::after {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;

    background: radial-gradient(
        circle,
        transparent 40%,
        rgba(0,0,0,0.85) 100%
    );

    z-index: 9999;
}

/* ===== TEXT ===== */

* {
    color: #e6c9c1 !important;
}

/* ===== TOP BAR ===== */

.navbar,
.header,
.header-container {
    background: rgba(10, 0, 0, 0.9) !important;
    border-bottom: 1px solid rgba(120, 40, 40, 0.3) !important;
}

/* ===== SIDEBAR ===== */

nav,
.left-col,
.rbx-left-col,
#navigation {
    background: rgba(5, 0, 0, 0.92) !important;
    border-right: 1px solid rgba(120, 40, 40, 0.3) !important;
}

/* ===== PANELS ===== */

.section,
.card,
.content,
.container-main,
.games-list-container,
.game-card-container {
    background: rgba(25, 5, 5, 0.85) !important;
    border: 1px solid rgba(140, 60, 60, 0.25) !important;
}

/* ===== SEARCH ===== */

input {
    background: rgba(30, 0, 0, 0.75) !important;
    border: 1px solid rgba(160, 80, 80, 0.35) !important;
    color: #ffe0e0 !important;
}

/* ===== BUTTONS ===== */

button,
.btn-primary,
.btn-secondary {
    background: rgba(60, 20, 20, 0.85) !important;
    border: 1px solid rgba(160, 80, 80, 0.4) !important;
    color: #ffe6e6 !important;
}

/* ===== LINKS ===== */

a {
    color: #d8a0a0 !important;
}

a:hover {
    color: #ffeaea !important;
}
}
